-- 由 tools/build_sql_merge.py 从 data/merged_sql/merged_sql.json 生成
-- 覆盖 11 个视图：stat_database、stat_user_tables、activity_agg、activity_running、activity_top10、locks、bgwriter、settings、database、prepared_xacts、dbstat_sum
-- 分页窗口：limit 100 offset 0（offset 只作用于可增长视图）
-- 每个内层子查询都带 limit/offset：平台 Agent 对输出有 102400 B 硬上限，超了整条任务失败。
-- 不要手改本文件；改视图定义后重跑生成脚本。
select (select json_agg(t) from ( select datname, numbackends, xact_commit, xact_rollback, deadlocks, conflicts, blks_read, blks_hit, blk_read_time, blk_write_time, tup_inserted, tup_updated, tup_deleted, tup_returned, tup_fetched, temp_files, temp_bytes, case when (blks_hit + blks_read) > 0 then round(blks_hit * 100.0 / (blks_hit + blks_read), 2) else 0 end as cache_hit_ratio from pg_stat_database order by datname limit 100 offset 0 ) t) as stat_database, (select json_agg(t) from ( select schemaname, relname, n_live_tup, n_dead_tup, n_tup_ins, n_tup_upd, n_tup_del, n_tup_hot_upd, seq_scan, seq_tup_read, idx_scan, idx_tup_fetch, case when (n_live_tup + n_dead_tup) > 0 then round(n_dead_tup * 100.0 / (n_live_tup + n_dead_tup), 2) else 0 end as dead_tup_ratio from pg_stat_user_tables order by dead_tup_ratio desc limit 100 offset 0 ) t) as stat_user_tables, (select json_agg(t) from ( select datname, state, count(*) as cnt from pg_stat_activity where state is not null group by datname, state order by datname, state limit 100 offset 0 ) t) as activity_agg, (select json_agg(t) from ( select datname, usename, state, query_start, query from pg_stat_activity where state = 'active' and query <> '' order by query_start desc limit 20 ) t) as activity_running, (select json_agg(t) from ( select datname, usename, query_start, query from pg_stat_activity where state = 'active' order by query_start limit 10 ) t) as activity_top10, (select json_agg(t) from ( select d.datname, l.locktype, l.mode, count(*) as cnt from pg_locks l join pg_database d on l.database = d.oid group by d.datname, l.locktype, l.mode order by d.datname, l.locktype, l.mode limit 100 offset 0 ) t) as locks, (select json_agg(t) from ( select buffers_alloc, buffers_backend, buffers_backend_fsync, buffers_checkpoint, buffers_clean, checkpoints_req, checkpoints_timed, maxwritten_clean from pg_stat_bgwriter limit 100 offset 0 ) t) as bgwriter, (select json_agg(t) from ( select name, setting, unit from pg_settings where name in ('max_connections', 'port', 'TimeZone', 'block_size') limit 100 offset 0 ) t) as settings, (select json_agg(t) from ( select datname, pg_encoding_to_char(encoding) as encoding, pg_database_size(datname) as size_bytes from pg_database order by size_bytes desc limit 100 offset 0 ) t) as database, (select json_agg(t) from ( select count(*) as prepared_xacts from pg_prepared_xacts limit 100 offset 0 ) t) as prepared_xacts, (select json_agg(t) from ( select d.datname, d.numbackends, d.xact_commit, d.xact_rollback, d.blks_read, d.blks_hit, t.schemaname, t.relname, t.n_live_tup, t.n_dead_tup, t.seq_scan, t.idx_scan, t.n_tup_ins, t.n_tup_upd, t.n_tup_del from pg_stat_database d left join pg_stat_user_tables t on d.datname = current_database() order by t.n_dead_tup desc limit 100 offset 0 ) t) as dbstat_sum
